<template><AppShell title="求购广场" tab="market"><view class="pad"><view class="notice"><AppIcon class="app-icon" name="info" :size="20" /><text>和平精英 · 地铁逃生。与买家聊好规格、数量和交付，再从卖家商品下单。</text></view><view class="tabs category-tabs"><button class="ui-button" v-for="c in categories" :key="c" :class="{selected:category===c}" @click="category=c;load()">{{c}}</button></view><view class="row sort-row"><button class="ui-button" :class="{bold:sort==='newest'}" @click="sort='newest';load()">最新求购</button><button class="ui-button" :class="{bold:sort==='priceDesc'}" @click="sort='priceDesc';load()">预算最高</button></view><StateView :loading="loading" :error="error" :count="items.length" title="暂时没有求购" description="切换道具分类，或稍后再来看看" @retry="load()" /><view v-for="item in items" :key="item.id" class="card"><view class="row" @click="go('service/detail',{id:item.id})"><GameArt variant="mini" class="mini-cover" game="和平精英" :src="images(item.images)[0]" /><view class="stack flex-1"><text class="bold">{{item.title}}</text><text class="price">预算 ¥{{money(item.priceCents)}}<text class="tiny">{{item.pricingMode==='UNIT'?' / 件':' / 整批'}}</text></text><text class="muted tiny">{{item.itemCategory}} · {{item.quantity}} 件 · {{item.zone}} / {{item.platform}}</text></view></view><text class="summary-text" style="display:block;margin:12px 0">{{item.itemDetails}}</text><view class="row between"><view class="request-owner row" role="button" :aria-label="'查看'+item.nickname+'的主页'" @click="go('shop/index',{id:item.ownerId})"><GameArt avatar :size="28" :type="item.avatar" :src="item.avatar?.startsWith('/')?item.avatar:''" /><text class="muted tiny">{{item.nickname}} · {{date(item.createdAt)}}</text></view><button class="ui-button btn small" @click="chatWith(item.ownerId,item.id)">联系买家</button></view></view><button v-if="items.length<total" class="ui-button load-more" :disabled="loading" @click="more">查看更多求购</button></view></AppShell></template>
<script setup>
import {ref} from 'vue';import {onShow,onReachBottom} from '@dcloudio/uni-app';import AppShell from '../../components/AppShell.vue';import AppIcon from '../../components/AppIcon.vue';import GameArt from '../../components/GameArt.vue';import StateView from '../../components/StateView.vue';import {useList} from '../../lib/useList';import {go,money,date,images,chatWith} from '../../lib/api';import {ITEM_CATEGORIES} from '../../lib/playerTrade'
const category=ref('全部'),sort=ref('newest'),categories=['全部',...ITEM_CATEGORIES];const{items,total,loading,error,load,more}=useList('/boost/listings',()=>({kind:'REQUEST',itemCategory:category.value,sort:sort.value}));onShow(()=>load());onReachBottom(more)
</script>
<style scoped>.category-tabs{overflow-x:auto;justify-content:flex-start;margin:14px 0}.category-tabs button{white-space:nowrap;flex-shrink:0}.sort-row{justify-content:space-around;font-size:12px;color:#888;margin-bottom:14px}.sort-row .bold{color:#191919}.card{padding:12px;margin-bottom:10px}.card .row{gap:10px}.card .bold{font-size:14px}</style>
